/* Agents editorial. Illustrations and demos explain roles; they do not execute model or business calls. */
const N_ROLES=[
{tab:'Atendimento',role:'Um atendimento que encontra o próximo passo.',intro:'Entender o pedido, consultar o contexto permitido e ajudar a pessoa a continuar.',person:'Cliente',message:'Preciso remarcar meu atendimento. Tem algum horário esta semana?',reply:'Posso consultar a disponibilidade para você escolher um novo horário.',tools:[['Consultar a agenda','calendar'],['Encontrar o contato','customers']],action:'Preparar a solicitação de remarcação',limit:'A alteração depende da escolha do cliente, das permissões e da confirmação prevista na jornada.',outcome:'Um horário foi escolhido na demonstração. A solicitação fica preparada para a confirmação definida pela operação.'},
{tab:'Copiloto',role:'A pessoa conduz. O agente apoia.',intro:'Reunir contexto, sugerir perguntas e preparar registros para o profissional revisar.',person:'Profissional',message:'Ajude a organizar as pendências e os próximos passos desta conversa.',reply:'Posso preparar um resumo do contexto autorizado e destacar o que precisa de conferência.',tools:[['Usar o contexto da conversa','rooms'],['Preparar um resumo','ai-engine']],action:'Preparar próximos passos para revisão',limit:'Sugestões e documentos são apoio ao profissional. A revisão continua com a pessoa responsável.',outcome:'Os próximos passos demonstrativos estão preparados para revisão. Nenhuma tarefa ou mensagem foi criada.'},
{tab:'Banking',role:'A conta tem informação. O cliente precisa de clareza.',intro:'Ajudar a interpretar a posição da conta e encaminhar a questão ao atendimento certo.',person:'Titular',message:'Por que meu saldo disponível é diferente do valor que aparece na conta?',reply:'Com o acesso permitido, posso consultar o contexto de saldo e reservas para explicar a diferença.',tools:[['Consultar a posição da conta','baas'],['Identificar o contexto de acesso','iam']],action:'Preparar um pedido de esclarecimento',limit:'Serviços bancários e autorizações ficam nas capacidades responsáveis. Explicar o saldo não autoriza movimentar dinheiro.',outcome:'Um pedido demonstrativo de esclarecimento está preparado para o atendimento. Não houve consulta real nem movimentação.'},
{tab:'Crédito',role:'Menos dúvida entre a proposta e a próxima etapa.',intro:'Localizar pendências e orientar o envio das informações necessárias, com a política no lugar certo.',person:'Cliente',message:'Minha proposta está parada. O que falta para continuar?',reply:'Posso consultar o contexto autorizado da proposta e ajudar a identificar o próximo passo.',tools:[['Consultar o contexto da proposta','data-store'],['Localizar os documentos','file-storage']],action:'Preparar uma solicitação de complemento',limit:'O agente orienta o atendimento. Critérios e decisões de crédito permanecem nas políticas e nos responsáveis da operação.',outcome:'A solicitação demonstrativa de complemento está pronta para revisão. Não houve avaliação nem decisão de crédito.'}
];
Object.assign(X_CAPTURE_META,{
'agents-overview.jpg':{product:'agents',title:'Agentes / Uma visão dos papéis configurados',desc:'Interface de gestão com agentes, ferramentas e estado de configuração.',type:'Gestão',origin:'Material da vitrine Catalisa · data original não informada'},
'agents-config.png':{product:'agents',title:'Configuração / Identidade antes da atuação',desc:'Passo inicial de configuração de um agente: identidade e personalidade, com etapas de habilidades, segurança, instruções e revisão.',type:'Configuração',origin:'Baseline de interface de 30/07/2026 · material de referência'}
});
function nHeroArt(){return `<svg class="n-hero-art" viewBox="0 0 680 610" role="img" aria-label="Uma lente de contexto conecta propósito, conhecimento e ferramentas"><defs><linearGradient id="agent-frame" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b597cd"/><stop offset="1" stop-color="#674187"/></linearGradient><radialGradient id="agent-lens"><stop stop-color="#ffe6c7"/><stop offset=".52" stop-color="#f3ae74"/><stop offset="1" stop-color="#d87d3e"/></radialGradient><filter id="agent-shadow"><feGaussianBlur stdDeviation="16"/></filter></defs><ellipse cx="356" cy="496" rx="192" ry="34" fill="#462950" opacity=".12" filter="url(#agent-shadow)"/><g fill="none" stroke="#c9b8d3" stroke-width=".7"><circle cx="345" cy="294" r="238"/><path d="M345 35V555M77 294H614" stroke-dasharray="3 9"/></g><g class="n-lens-body"><rect x="190" y="146" width="318" height="318" rx="58" fill="#5d367c" transform="rotate(-11 349 305) translate(7 13)"/><rect x="190" y="146" width="318" height="318" rx="58" fill="url(#agent-frame)" transform="rotate(-11 349 305)"/><circle cx="347" cy="304" r="110" fill="#503265"/><circle cx="347" cy="294" r="107" fill="url(#agent-lens)"/><circle cx="347" cy="294" r="70" fill="#f8ecdf"/><circle cx="347" cy="294" r="42" fill="#9770b1"/><circle cx="347" cy="294" r="16" fill="#e4d3ee"/><path d="M274 220a104 104 0 0 1 114-26" stroke="#ffe4c1" stroke-width="2" fill="none"/></g><g class="n-context-note"><rect x="83" y="125" width="152" height="80" rx="4" fill="#f9f5ed" stroke="#d6c7df"/><path d="M105 150H211M105 166H185M105 182H198" stroke="#c7b1d5"/><circle cx="221" cy="190" r="5" fill="#edb74f"/></g><g class="n-tool-note"><rect x="460" y="350" width="136" height="100" rx="4" fill="#ebe2f0" stroke="#c9b4d7"/><path d="M491 376h30v30h-30zM537 376h30v30h-30zM506 406v19h46v-19" stroke="#a27fb8" fill="none"/><circle cx="552" cy="422" r="5" fill="#e4995c"/></g><g fill="#aa8ab9" font-family="monospace" font-size="9" letter-spacing="1.5"><text x="105" y="107">CONTEXTO</text><text x="480" y="477">FERRAMENTAS</text><text x="227" y="543">UM PAPEL. CONEXÕES COM PROPÓSITO.</text></g></svg>`}
function nDemo(i=0,permission='read',prepared=false){const r=N_ROLES[i];return `<div class="n-demo-head"><div><span class="label">${r.tab} / Uma atuação possível</span><h3>${r.role}</h3><p>${r.intro}</p></div><div class="n-permission"><span>Explore o nível de acesso</span><div role="group" aria-label="Acesso demonstrativo"><button data-n-access="read" aria-pressed="${permission==='read'}">Consultar</button><button data-n-access="prepare" aria-pressed="${permission==='prepare'}">Preparar ação</button></div></div></div><div class="n-demo-stage"><div class="n-chat"><div class="n-chat-person"><span>${r.person}</span><p>${r.message}</p></div><div class="n-chat-agent"><span>Agente / Com contexto autorizado</span><p>${r.reply}</p></div><div class="n-chat-note"><i aria-hidden="true"></i>Conversas ilustrativas. Nenhum modelo ou sistema é consultado.</div></div><div class="n-action-panel"><span class="label">O que sustenta a resposta</span><div class="n-tool-trace">${r.tools.map(([name,slug],j)=>`<a href="/capacidades/${slug}/"><span>0${j+1}</span><strong>${name}</strong><small>Capacidade relacionada ↗</small></a>`).join('')}</div><div class="n-next-action"><span>${permission==='read'?'Acesso de consulta':'Ação preparada, sujeita à revisão'}</span><h4>${r.action}</h4><p>${permission==='read'?'Neste modo demonstrativo, o agente consulta e orienta. Preparar uma ação exige o acesso correspondente.':r.limit}</p><button data-n-prepare ${permission==='read'?'disabled':''}>${prepared?'Preparação demonstrativa concluída':'Ver próximo passo'} <span>↗</span></button>${prepared?`<p class="n-demo-outcome" role="status">${r.outcome}</p>`:''}</div></div></div>`}
function nPrint(file,title,copy,origin){return `<figure class="n-print"><div class="n-print-bar"><span>${title}</span><small>Ampliar ↗</small></div><button data-gallery-file="${file}" data-gallery-product="agents" aria-label="Ampliar ${title}"><img src="/assets/screens/${file}" alt="${ce(copy)}" loading="lazy"></button><figcaption><p>${copy}</p><small>${origin}</small></figcaption></figure>`}
function nPage(){return `<div class="n-page"><section class="n-hero"><div class="wrap"><div><span class="label">Catalisa / Agentes IA</span><h1>Entender<br>o contexto.<br><em>Agir com sentido.</em></h1><p>Agentes conectam a conversa ao trabalho. Um papel claro, informações autorizadas e ferramentas escolhidas dão direção à atuação.</p><a class="text-link" href="#atuacao">Explore os papéis de um agente ↓</a></div><div class="n-hero-object">${nHeroArt()}</div></div><div class="n-hero-foot wrap"><span>O valor aparece quando a inteligência encontra a operação.</span><button data-n-motion aria-pressed="false">Ⅱ Pausar movimento</button></div></section><section class="n-manifesto wrap"><span class="label">A inteligência faz parte de uma composição</span><h2>Uma conversa pode<br>encontrar uma informação.<br><em>E também um próximo passo.</em></h2><div><p>Um agente usa o contexto disponível para interpretar um pedido e escolher como responder. Quando possui as ferramentas e os acessos necessários, pode participar das ações que dão continuidade à jornada.</p><p>O desenho começa pelo trabalho: quem ele apoia, quais informações pode consultar e até onde pode ir. A atuação ganha sentido dentro dessa responsabilidade.</p></div></section><section class="n-foundation"><div class="wrap"><div class="n-foundation-title"><span class="label">Três perguntas que dão forma</span><h2>Um agente precisa<br>saber o seu lugar.</h2></div><div class="n-foundation-rail">${[['01','Para quê?','O propósito','Objetivo, tom, instruções e critérios de encaminhamento orientam a atuação.'],['02','Com o quê?','O contexto','A conversa e as informações autorizadas ajudam a compreender o pedido.'],['03','Até onde?','As ferramentas','Ações e acessos definidos conectam o agente ao que a operação permite.']].map(([n,q,t,p])=>`<article><span>${n}</span><div class="n-foundation-symbol" aria-hidden="true">${q}</div><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="n-roles wrap" id="atuacao"><div class="n-section-heading"><div><span class="label">O papel muda com o negócio</span><h2>Apoio na conversa.<br>Continuidade na operação.</h2></div><p>Explore os contextos e o nível de acesso.<br>A mesma ideia de agente encontra trabalhos diferentes.</p></div><div class="n-role-tabs" role="tablist" aria-label="Papéis de agentes">${N_ROLES.map((r,i)=>`<button role="tab" id="n-role-${i}" data-n-role="${i}" aria-controls="n-demo" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${r.tab}</button>`).join('')}</div><div id="n-demo" role="tabpanel" aria-labelledby="n-role-0">${nDemo()}</div></section><section class="n-knowledge"><div class="wrap"><div><span class="label">Contexto que acompanha a conversa</span><h2>Continuar começa<br>por reconhecer<br><em>o que já foi dito.</em></h2><p>A continuidade pode reutilizar o histórico da conversa dentro do período configurado. A informação de uma mensagem ajuda a interpretar a seguinte.</p><p>Esse contexto tem limites: duração da sessão, dados disponíveis e acesso da pessoa. O desenho precisa definir quando retomar, quando perguntar e quando encaminhar.</p></div><div class="n-continuity-art"><span>UMA CONVERSA, COM CONTINUIDADE</span><div class="n-message-line"><small>Primeiro contato</small><p>“Quero marcar um atendimento.”</p><i></i></div><div class="n-message-line"><small>Na mesma conversa</small><p>“Prefiro no período da tarde.”</p><i></i></div><div class="n-context-memory"><span>O contexto conecta as mensagens.</span><strong>Agendamento<br>+ preferência de horário</strong></div><small>Exemplo ilustrativo. Continuidade e prazo de sessão dependem da configuração.</small></div></div></section><section class="n-tools wrap"><div class="n-section-heading"><div><span class="label">Ferramentas conectam intenção e capacidade</span><h2>O agente encontra<br>as peças do trabalho.</h2></div><p>Uma ferramenta dá acesso a uma operação.<br>Seu uso precisa respeitar o papel e as permissões.</p></div><div class="n-tools-index">${[['customers','Relacionamento','Encontrar o contato e continuar o atendimento com os dados disponíveis.'],['calendar','Agenda','Consultar disponibilidade e preparar o próximo encontro.'],['wpp-business','Comunicação','Participar da conversa pelo canal oficial conectado à operação.'],['file-storage','Documentos','Acessar os arquivos que a jornada disponibiliza e autoriza.'],['ai-engine','Interpretação','Apoiar resumos, classificação e leitura de informações.'],['data-store','Contexto da operação','Consultar e atualizar informações conforme a composição e os acessos.']].map(([slug,t,p],i)=>`<a href="/capacidades/${slug}/"><span>0${i+1}</span><div><h3>${t}</h3><p>${p}</p></div><i aria-hidden="true">↗</i></a>`).join('')}</div></section><section class="n-boundaries"><div class="wrap"><div><span class="label">Autonomia com fronteiras</span><h2>As instruções orientam.<br><em>As permissões delimitam.</em></h2><p>Uma orientação de texto ajuda a definir o comportamento. O acesso às ações precisa de controles próprios, configurados na plataforma e na jornada.</p>${ca('/governanca/','Aprofunde a governança')}</div><div class="n-boundary-points">${[['Quem está pedindo?','O papel e o contexto de acesso importam para saber o que pode ser consultado ou realizado.'],['Qual ação está disponível?','Selecione ferramentas e configure os controles aplicáveis. Dar um nome a uma ação não deve significar acesso irrestrito.'],['O que exige uma pessoa?','Aprovações e ações sensíveis precisam de uma experiência de revisão definida pela operação.'],['O que fazer quando não sabe?','Ausência de informação, dúvida e falha devem encontrar encaminhamento, em vez de uma resposta inventada.']].map(([t,p],i)=>`<article><span>0${i+1}</span><div><h3>${t}</h3><p>${p}</p></div></article>`).join('')}</div></div></section><section class="n-interface wrap"><div class="n-section-heading"><div><span class="label">O papel ganha configuração</span><h2>Da intenção à identidade.<br>Da identidade às ferramentas.</h2></div><p>Uma visão da gestão de agentes<br>e do início de sua configuração.</p></div><div class="n-print-gallery"><div>${nPrint('agents-overview.jpg','Gestão / Papéis e ferramentas','Uma visão dos agentes configurados, com ferramentas e estado de configuração.','Material da vitrine Catalisa · data original não informada')}</div><div class="n-print-aside"><span class="label">Construir com clareza</span><h3>Nome, propósito<br>e comportamento<br>são o começo.</h3><p>A configuração aproxima a intenção das habilidades e instruções escolhidas para o agente. O Studio ajuda a estruturar essa construção.</p>${ca('/studio/','Conheça o Studio')}</div></div><div class="n-config-exhibit">${nPrint('agents-config.png','Configuração / Identidade do agente','Referência da interface de criação de agente, com etapas de identidade, habilidades, segurança, instruções e revisão.','Baseline de interface de 30/07/2026 · dados de demonstração')}<p>Capturas preservadas no repositório. São referências de interface, não evidências de desempenho ou de uma conversa em execução. Clique para ampliar.</p></div></section><section class="n-composition"><div class="wrap"><div><span class="label">Cada parte tem um papel</span><h2>O agente interpreta.<br>O fluxo conecta.<br>O produto dá contexto.</h2><p>Construir uma experiência completa envolve mais que configurar uma conversa. As capacidades e as regras de negócio precisam se encontrar no mesmo desenho.</p></div><nav aria-label="Explore a composição"><a href="/studio/"><span>Construir</span><strong>Studio</strong><p>Estruturar a necessidade, revisar o plano e selecionar as conexões.</p><i aria-hidden="true">↗</i></a><a href="/workflows/"><span>Orquestrar</span><strong>Workflows</strong><p>Organizar eventos, condições e ações ao longo da jornada.</p><i aria-hidden="true">↗</i></a><a href="/capacidades/"><span>Realizar</span><strong>Building Blocks</strong><p>Encontrar capacidades com responsabilidades e estágios próprios.</p><i aria-hidden="true">↗</i></a></nav></div></section><section class="n-questions wrap"><div><span class="label">Para desenhar a atuação</span><h2>Autonomia começa<br>com clareza.</h2></div><div>${[
['Preciso dar acesso a todas as ferramentas?','Não. Escolha as ferramentas necessárias para o papel do agente e configure os acessos e controles aplicáveis. Uma responsabilidade delimitada ajuda a observar e validar o comportamento.'],
['O agente lembra de qualquer conversa para sempre?','Não. A continuidade depende da configuração da sessão e do período de inatividade permitido. Histórico de conversa também não equivale a acesso irrestrito aos dados da empresa.'],
['Um copiloto é a mesma coisa que atendimento automático?','São papéis diferentes. Um copiloto pode apoiar o profissional durante uma conversa e preparar registros para revisão. Um atendimento automatizado interage diretamente com o cliente, dentro das regras e permissões definidas.'],
['O agente decide as regras do negócio?','As regras precisam estar explícitas e nas capacidades responsáveis. O agente pode interpretar o pedido e usar ferramentas, mas o desenho deve preservar políticas, autorizações e revisões da operação.'],
['Posso usar os sistemas que já tenho?','Ferramentas e integrações podem conectar o agente às informações e ações de sistemas existentes. Isso depende das interfaces disponíveis, credenciais, contratos e permissões necessários.'],
['Como começo a avaliar?','Escolha um papel e uma jornada curta. Defina o objetivo, os dados permitidos, as ferramentas e os momentos de encaminhamento. Valide o comportamento antes de ampliar a atuação.']
].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">＋</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="n-closing"><div class="wrap"><span class="label">Da inteligência ao trabalho que importa</span><h2>Escolha um propósito.<br>Encontre as conexões.</h2><div>${ca('/lab/','Imagine seu produto')}${ca('/contato/','Converse sobre a composição')}</div><span class="n-closing-object" aria-hidden="true"></span></div></section></div>`}
const nOriginalPage=cPage;cPage=function(route,blocks){return route==='/agentes/'?nPage():nOriginalPage(route,blocks)};
function nBind(){const root=document.querySelector('.n-page');if(!root)return;let role=0,access='read',prepared=false;const panel=document.getElementById('n-demo'),tabs=[...root.querySelectorAll('[data-n-role]')];const render=()=>{panel.innerHTML=nDemo(role,access,prepared);panel.setAttribute('aria-labelledby','n-role-'+role)};tabs.forEach((b,i)=>{b.addEventListener('click',()=>{role=i;access='read';prepared=false;tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});render()});b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();tabs[n].focus()})});panel.addEventListener('click',e=>{const permission=e.target.closest('[data-n-access]');if(permission){access=permission.dataset.nAccess;prepared=false;render();panel.querySelector('[data-n-access="'+access+'"]').focus({preventScroll:true})}if(e.target.closest('[data-n-prepare]')&&access==='prepare'){prepared=true;render();panel.querySelector('[data-n-prepare]').focus({preventScroll:true})}});root.querySelector('[data-n-motion]').addEventListener('click',e=>{const paused=root.classList.toggle('n-motion-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'▶ Retomar movimento':'Ⅱ Pausar movimento'})}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',nBind);
